webpackJsonp([0x694f1db5b903],{421:function(a,e){a.exports={data:{site:{siteMetadata:{title:"Mihail Eric",subtitle:"Engineer, researcher, educator.",copyright:"Copyright",author:{name:"Mihail Eric",twitter:"mihail_eric"},url:"https://mihaileric.com"}},allMarkdownRemark:{edges:[{node:{fields:{slug:"/posts/principal-components-analysis/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Principal Components Analysis",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/nlp-trends-acl-2019/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Trends in Natural Language Processing: ACL 2019 In Review",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2019-08-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/what-kmeans-clustering/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"What K-Means",tags:["Machine Learning","A.I.","Data Science"],date:"2019-07-16T23:46:37.121"}}},{node:{fields:{slug:"/posts/recurrent-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Recurrent Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:46:37.121"}}},{node:{fields:{slug:"/posts/convolutional-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Dance Dance Convolution",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/neural-network-grab-bag/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Neural Network Grab Bag",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T22:46:37.121"}}},{node:{fields:{slug:"/posts/deep-dive-into-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Deep Dive Into Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-04-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/support-vector-machines/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Basics of Support Vector Machines",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-20T23:46:37.121"}}},{node:{fields:{slug:"/posts/not-so-naive-bayes/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why So Naive, Bayes?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-13T23:46:37.121"}}},{node:{fields:{slug:"/posts/introduction-to-logistic-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Introduction to Logistic Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamentals-of-linear-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Fundamentals of Linear Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-03-15T23:46:37.121"}}},{node:{fields:{slug:"/posts/transformers-attention-in-disguise/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Transformers: Attention in Disguise",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-22T23:46:37.121"}}},{node:{fields:{slug:"/posts/deep-contextualized-word-representations-elmo/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Deep Contextualized Word Representations with ELMo",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fast-object-detection-with-fast-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Fast Object Detection with Fast R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/object-detection-with-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Object Detection with R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamental-deep-learning-algorithms-to-learn/",tagSlugs:["/tags/a-i/","/tags/deep-learning/","/tags/machine-learning/"]},frontmatter:{title:"Fundamental Deep Learning Algorithms To Learn",tags:["A.I.","Deep Learning","Machine Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/why-all-the-excitement-about-ai/",tagSlugs:["/tags/a-i/","/tags/machine-learning/","/tags/deep-learning/"]},frontmatter:{title:"Why All The Excitement About Artificial Intelligence",tags:["A.I.","Machine Learning","Deep Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/being-a-good-machine-learning-data-scientist/",tagSlugs:["/tags/a-i/","/tags/data-science/","/tags/machine-learning/"]},frontmatter:{title:"Being a Good Machine Learning Engineer/Data Scientist",tags:["A.I.","Data Science","Machine Learning"],date:"2018-08-11T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-software-interview-challenge/",tagSlugs:["/tags/software-engineering/","/tags/interview-prep/"]},frontmatter:{title:"A Software Interview Challenge",tags:["Software Engineering","Interview Prep"],date:"2017-12-24T23:46:37.121"}}},{node:{fields:{slug:"/posts/review-of-sigdial-semdial-2017/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Review of SIGDial/SemDial 2017",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2017-09-04T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-new-multiturn-dialogue-dataset/",tagSlugs:["/tags/natural-language-processing/","/tags/dataset/","/tags/dialogue/"]},frontmatter:{title:"A New Multi-Turn, Multi-Domain, Task-Oriented Dialogue Dataset",tags:["Natural Language Processing","Dataset","Dialogue"],date:"2017-07-03T23:46:37.121"}}}]},markdownRemark:{id:"/Users/mihaileric/Documents/Projects/mihail911.github.io/src/pages/articles/2019-04-04---Convolutional-Networks/index.md absPath of file >>> MarkdownRemark",html:'<figure>\n    \n  <a class="gatsby-resp-image-link" href="/static/neo_convnets_meme-a4dc4674c5e5b710c18b7fa3e014cf3b-cbad6.jpg" style="display: block" target="_blank" rel="noopener">\n  \n  <span class="gatsby-resp-image-wrapper" style="position: relative; display: block; ; max-width: 300px; margin-left: auto; margin-right: auto;">\n    <span class="gatsby-resp-image-background-image" style="padding-bottom: 95.66666666666666%; position: relative; bottom: 0; left: 0; background-image: url(&apos;data:image/jpeg;base64,&apos;); background-size: cover; display: block;">\n      <img class="gatsby-resp-image-image" style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;" alt="neo convolutional neural networks meme" title="" src="/static/neo_convnets_meme-a4dc4674c5e5b710c18b7fa3e014cf3b-cbad6.jpg" srcset="/static/neo_convnets_meme-a4dc4674c5e5b710c18b7fa3e014cf3b-a62cd.jpg 240w,\n/static/neo_convnets_meme-a4dc4674c5e5b710c18b7fa3e014cf3b-cbad6.jpg 300w" sizes="(max-width: 300px) 100vw, 300px">\n    </span>\n  </span>\n  \n  </a>\n    \n</figure>\n<p>About 9 years ago, the <a href="http://www.image-net.org/challenges/LSVRC/">ImageNet challenge</a>, an annual visual recognition competition was begun. In the challenge, teams\nwere tasked with building the best object classifier on a collection of images from a set of 1000 possible object labels. </p>\n<p>In the year 2011, a team from the University of Toronto trounced the competition by introducing the world’s first successful image recognition system built entirely\nusing neural networks.</p>\n<p>This milestone helped to trigger the artificial intelligence wave that we are\ncurrently experiencing. Today we are going to investigate the neural network architecture that was at the heart\nof this revolutionary point in history. Excited? Let’s get to it!</p>\n<h2>Motivations</h2>\n<p>The neural network class that was at the heart of the deep learning revolution is called <strong>convolutional neural networks</strong>.\nTo motivate their design, we will start with the problem of image recognition. Consider the following image:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/dog2-36d9d7c3d667c0a0a6091ad169aba909-c3eb1.jpg"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 720px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 100%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/jpeg;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Dog Imagenet image"\n        title=""\n        src="/static/dog2-36d9d7c3d667c0a0a6091ad169aba909-c3eb1.jpg"\n        srcset="/static/dog2-36d9d7c3d667c0a0a6091ad169aba909-3d038.jpg 240w,\n/static/dog2-36d9d7c3d667c0a0a6091ad169aba909-b01b9.jpg 480w,\n/static/dog2-36d9d7c3d667c0a0a6091ad169aba909-c3eb1.jpg 720w"\n        sizes="(max-width: 720px) 100vw, 720px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Our brains are amazing because we are able to just about instantaneously recognize that this image contains a cute puppy.\nWhat allows us to recognize that this is a puppy?</p>\n<p>Our brains are keen at picking up relevant features in an image,\nscanning efficiently for the things that are necessary for us to differentiate the image. Consider a more complicated\nexample:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/pollockesque-963d246c908036a09715a881ae614690-b6d5f.jpg"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 500px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 61.8%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/jpeg;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Polleck image confusion"\n        title=""\n        src="/static/pollockesque-963d246c908036a09715a881ae614690-b6d5f.jpg"\n        srcset="/static/pollockesque-963d246c908036a09715a881ae614690-0f47f.jpg 240w,\n/static/pollockesque-963d246c908036a09715a881ae614690-696e5.jpg 480w,\n/static/pollockesque-963d246c908036a09715a881ae614690-b6d5f.jpg 500w"\n        sizes="(max-width: 500px) 100vw, 500px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Here it’s not immediately clear what this is a picture of, so we must analyze the picture more deliberately. We may\nstart at the upper left corner and scan horizontally, picking out details that seem relevant.</p>\n<p>After we have scanned the entire image, our brain holistically tries to put together the pieces into some impression of the image subject.\nThis intuition for how our own vision system seems to work by scanning and picking out features will be a useful analogy\nfor convolutional networks.</p>\n<h2>The Convolutional Layer</h2>\n<p>Let’s revisit how we represent images mathematically. Recall that images can be represented as a 3-d tensor of (<span style="color:red">red</span>, <span style="color:green">green</span>, <span style="color:blue">blue</span>) color channels. Previously when we were studying <a href="/posts/deep-dive-into-neural-networks/">feedforward networks</a> we collapsed this 3-d representation into a single dimensional vector. It turns out in practice this vector collapsing is not really done for images.</p>\n<p>Instead imagine that we have some <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mi>x</mi><mn>4</mn><mi>x</mi><mn>3</mn></mrow><annotation encoding="application/x-tex">4x4x3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">4</span><span class="mord mathit">x</span><span class="mord">4</span><span class="mord mathit">x</span><span class="mord">3</span></span></span></span> image and we keep it in its 3-dimensional format. We will aim to process our image by running it through a series of layerwise computations, similarly to how we did for feedforward networks. To do that we will take a <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mi>x</mi><mn>2</mn><mi>x</mi><mn>3</mn></mrow><annotation encoding="application/x-tex">2x2x3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">3</span></span></span></span> tensor of weights, which we will call a <strong>filter</strong>, as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/convImage1Diagram-c85fc547ad44ff55b27b0db3e8f81559-5cb0d.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 712px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 66.01123595505618%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Convolutional network image 1 diagram"\n        title=""\n        src="/static/convImage1Diagram-c85fc547ad44ff55b27b0db3e8f81559-5cb0d.png"\n        srcset="/static/convImage1Diagram-c85fc547ad44ff55b27b0db3e8f81559-5fcf9.png 240w,\n/static/convImage1Diagram-c85fc547ad44ff55b27b0db3e8f81559-0fd0d.png 480w,\n/static/convImage1Diagram-c85fc547ad44ff55b27b0db3e8f81559-5cb0d.png 712w"\n        sizes="(max-width: 712px) 100vw, 712px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Let’s begin by applying our filter to the upper left <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mi>x</mi><mn>2</mn><mi>x</mi><mn>3</mn></mrow><annotation encoding="application/x-tex">2x2x3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">3</span></span></span></span> corner of the image. The way this is done is we chop up\nour filter into 3 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mi>x</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">2x2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">2</span></span></span></span> depth slices:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/filterDeconstructDiagram-962e688d803a586603ad16ee6db34d4e-1b547.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 564px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 87.58865248226951%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Convolutional neural network image deconstructed into filters"\n        title=""\n        src="/static/filterDeconstructDiagram-962e688d803a586603ad16ee6db34d4e-1b547.png"\n        srcset="/static/filterDeconstructDiagram-962e688d803a586603ad16ee6db34d4e-debc1.png 240w,\n/static/filterDeconstructDiagram-962e688d803a586603ad16ee6db34d4e-42e3d.png 480w,\n/static/filterDeconstructDiagram-962e688d803a586603ad16ee6db34d4e-1b547.png 564w"\n        sizes="(max-width: 564px) 100vw, 564px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>We do the same for the corner of the image we are interested in looking at:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/imageDeconstructDiagram-7f113f1f0dd37c0f45b99bb176282cd6-bc95f.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 646px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 80.80495356037152%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Convolutional neural network image deconstructed "\n        title=""\n        src="/static/imageDeconstructDiagram-7f113f1f0dd37c0f45b99bb176282cd6-bc95f.png"\n        srcset="/static/imageDeconstructDiagram-7f113f1f0dd37c0f45b99bb176282cd6-64fb9.png 240w,\n/static/imageDeconstructDiagram-7f113f1f0dd37c0f45b99bb176282cd6-530fd.png 480w,\n/static/imageDeconstructDiagram-7f113f1f0dd37c0f45b99bb176282cd6-bc95f.png 646w"\n        sizes="(max-width: 646px) 100vw, 646px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Then we take the pairs of (depth-wise) matching slices and perform an element-wise multiplication. At the end, we take the 3 values we get from these depth-wise operations and we sum them together. That looks as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/convMultiplyDiagram-46cbf71841e361ce44807b619281f774-46426.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 742px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 77.08894878706198%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Convolutional neural network filter multiply"\n        title=""\n        src="/static/convMultiplyDiagram-46cbf71841e361ce44807b619281f774-46426.png"\n        srcset="/static/convMultiplyDiagram-46cbf71841e361ce44807b619281f774-ffb58.png 240w,\n/static/convMultiplyDiagram-46cbf71841e361ce44807b619281f774-4f0e9.png 480w,\n/static/convMultiplyDiagram-46cbf71841e361ce44807b619281f774-46426.png 742w"\n        sizes="(max-width: 742px) 100vw, 742px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>For those that are mathematically-inclined, we just took a 3-d dot product! This computed value will be the first element in the next layer\nof our neural network. Now, we slide our filter to the right to the next <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mi>x</mi><mn>2</mn><mi>x</mi><mn>3</mn></mrow><annotation encoding="application/x-tex">2x2x3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">3</span></span></span></span> volume of the image and perform the same operation:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/topRightConvDiagram-915732fbc2d8a2b8de0ff40db1694f85-29da9.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 868px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 51.1520737327189%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Top right filter multiplication in convolutional neural network"\n        title=""\n        src="/static/topRightConvDiagram-915732fbc2d8a2b8de0ff40db1694f85-29da9.png"\n        srcset="/static/topRightConvDiagram-915732fbc2d8a2b8de0ff40db1694f85-5e32d.png 240w,\n/static/topRightConvDiagram-915732fbc2d8a2b8de0ff40db1694f85-e413e.png 480w,\n/static/topRightConvDiagram-915732fbc2d8a2b8de0ff40db1694f85-29da9.png 868w"\n        sizes="(max-width: 868px) 100vw, 868px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Note that we also could slide our filter over one pixel, rather than two as we have done. The exact number\nof pixels that we slide over is a hyperparameter we can choose. After this, we move our filter to the lower-left corner of the image:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/lowerLeftConvDiagram-83c946f66f090b4cf521a4de05804f77-836c1.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 856px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 54.90654205607477%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Lower left filter multiplication in convolutional neural network"\n        title=""\n        src="/static/lowerLeftConvDiagram-83c946f66f090b4cf521a4de05804f77-836c1.png"\n        srcset="/static/lowerLeftConvDiagram-83c946f66f090b4cf521a4de05804f77-954c5.png 240w,\n/static/lowerLeftConvDiagram-83c946f66f090b4cf521a4de05804f77-4c942.png 480w,\n/static/lowerLeftConvDiagram-83c946f66f090b4cf521a4de05804f77-836c1.png 856w"\n        sizes="(max-width: 856px) 100vw, 856px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>and compute the same operation. We then do the same operation again, after sliding our filter horizontally. At the end, we have\nfour values in this first slice of our next layer:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/firstFilterDiagram-ea6a0005676d91ed652b1d7b2f5ca1f3-44a3b.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 49.29859719438878%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="First filter multiplication in convolutional neural network"\n        title=""\n        src="/static/firstFilterDiagram-ea6a0005676d91ed652b1d7b2f5ca1f3-3d61e.png"\n        srcset="/static/firstFilterDiagram-ea6a0005676d91ed652b1d7b2f5ca1f3-d182c.png 240w,\n/static/firstFilterDiagram-ea6a0005676d91ed652b1d7b2f5ca1f3-5220f.png 480w,\n/static/firstFilterDiagram-ea6a0005676d91ed652b1d7b2f5ca1f3-3d61e.png 960w,\n/static/firstFilterDiagram-ea6a0005676d91ed652b1d7b2f5ca1f3-44a3b.png 998w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Exciting! This is our first example of a <strong>convolution</strong>! The results of applying this filter form one slice of this next layer in our network.</p>\n<p>It turns out we can use another filter with new weights on this same image to get <em>another</em> slice in the next layer.</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/secondFilterDiagram-c30df39b039426798d43d7307c917471-13ce6.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 42.93893129770993%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Second filter multiplication in convolutional neural network"\n        title=""\n        src="/static/secondFilterDiagram-c30df39b039426798d43d7307c917471-3d61e.png"\n        srcset="/static/secondFilterDiagram-c30df39b039426798d43d7307c917471-d182c.png 240w,\n/static/secondFilterDiagram-c30df39b039426798d43d7307c917471-5220f.png 480w,\n/static/secondFilterDiagram-c30df39b039426798d43d7307c917471-3d61e.png 960w,\n/static/secondFilterDiagram-c30df39b039426798d43d7307c917471-13ce6.png 1048w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>In theory we can use as many unique filters as we want in our convolution, though the number to use becomes a hyperparameter we can tune.</p>\n<p>When we are done applying filters, the output of these filter operations are stacked together to get our complete next layer. If we had used 10 filters in the first layer of our running example, our second layer would be a <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mi>x</mi><mn>2</mn><mi>x</mi><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">2x2x10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">1</span><span class="mord">0</span></span></span></span> tensor of values. This transformation from input to output using filter convolutions is appropriately called a <strong>convolutional layer</strong>.</p>\n<p>Note that once we have our second layer, we can start from scratch and apply another convolutional layer if we so choose. Notice also that as we apply our convolutions, the length and width dimensions of our tensors tend to get smaller.</p>\n<p>The depth of our output layer is equal to the number of filters we use for our transformation, so depending on\nthat number, we might also reduce the depth dimension. For this reason, convolutional layers can be viewed as a form of feature reduction.</p>\n<p>One of the most elegant things about the convolution layer is that it has a very natural analogy to how humans compose their understanding of complex images.</p>\n<p>When we see something like a puppy our visual understanding process may first pick out prominent points like eyes and the nose. It may then create a notion of edges that form the outline of the dog. We then may add textures to the outline and colors. This hierarchical process allows us to decompose images into smaller constituents that we use to build up our understanding.</p>\n<p>In a similar fashion, convolutional networks can also learn hierarchical features as we go up the layers. Certain works have demonstrated\nthat when you actually visualize what is being learned at the layers of a convolutional network, we see visual entities of increasing complexity (points, lines, edges, etc.) as we go deeper into the network. This is really cool!</p>\n<p>In addition to this nice intuitive design and interpretability, what else do we gain by using convolutions instead of our original feedforward fully connected layers? When we use convolutional layers, we also see a drastic reduction in the number of weights we need in a given layer.</p>\n<p>Imagine if we collapsed a reasonably-sized image of dimensions <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mi>x</mi><mn>1</mn><mn>0</mn><mn>0</mn><mi>x</mi><mn>3</mn></mrow><annotation encoding="application/x-tex">100x100x3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">1</span><span class="mord">0</span><span class="mord">0</span><span class="mord mathit">x</span><span class="mord">1</span><span class="mord">0</span><span class="mord">0</span><span class="mord mathit">x</span><span class="mord">3</span></span></span></span> into a 30,000-length vector. If we wanted to make a fully-connected layer, each compute unit in the first layer would be connected to every value in the input, creating 30,000 weights. If we had even a moderately-sized first layer of 100 units, we would have <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn><mo>⋅</mo><mn>1</mn><mn>0</mn><mn>0</mn><mo>=</mo><mn>3</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">30,000 \\cdot 100 = 3,000,0000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base"><span class="mord">3</span><span class="mord">0</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord">0</span><span class="mord">0</span><span class="mord">0</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord">1</span><span class="mord">0</span><span class="mord">0</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord">0</span><span class="mord">0</span><span class="mord">0</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord">0</span><span class="mord">0</span><span class="mord">0</span><span class="mord">0</span></span></span></span> parameters just in the first layer! This clearly is not scalable.</p>\n<p>On the other hand, if we didn’t collapse the image and used a <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mi>x</mi><mn>5</mn></mrow><annotation encoding="application/x-tex">5x5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">5</span><span class="mord mathit">x</span><span class="mord">5</span></span></span></span> filter for a convolution, we would have <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>⋅</mo><mn>5</mn><mo>⋅</mo><mn>3</mn><mo>=</mo><mn>7</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">5 \\cdot 5 \\cdot 3 = 75</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">5</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord">5</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord">3</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mord">7</span><span class="mord">5</span></span></span></span> weights per filter. Even if we used a relatively large number of filters like 200, we would have a total of <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mn>0</mn><mo>⋅</mo><mn>7</mn><mn>5</mn><mo>=</mo><mn>1</mn><mn>5</mn><mo separator="true">,</mo><mn>0</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">200 \\cdot 75 = 15,000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base"><span class="mord">2</span><span class="mord">0</span><span class="mord">0</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord">7</span><span class="mord">5</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mord">1</span><span class="mord">5</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord">0</span><span class="mord">0</span><span class="mord">0</span></span></span></span> weights in the first layer which is a <strong>huge</strong> reduction! In this way, convolutional layers are more memory-efficient and compute-efficient when it comes to dealing with images.</p>\n<h2>Convolutional Network Mechanics</h2>\n<p>There are a number of design decisions in the convolutional layer that we can play with that influence the network’s learning\nability. For starters, we can certainly say a bit more about the dimensions of the filters applied.</p>\n<p>In practice, we can see filter sizes anywhere from <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mi>x</mi><mn>1</mn></mrow><annotation encoding="application/x-tex">1x1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">1</span><span class="mord mathit">x</span><span class="mord">1</span></span></span></span> to upwards of <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>1</mn><mi>x</mi><mn>1</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">11x11</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">1</span><span class="mord">1</span><span class="mord mathit">x</span><span class="mord">1</span><span class="mord">1</span></span></span></span> in some research papers. Note also that when applying a <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mi>x</mi><mn>1</mn></mrow><annotation encoding="application/x-tex">1x1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">1</span><span class="mord mathit">x</span><span class="mord">1</span></span></span></span> filter, we wouldn’t actually reduce the length and width dimensions of the layer we are convolving.</p>\n<p>In addition, there’s another design factor that we’ve used without formally defining. When we were sweeping our filter across the image in our motivating example, we were moving the filter over two pixels in a given dimension at a time as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/stride2Diagram-0703a55beb4a2fd5da9f95b2b24312c9-8f9ab.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 440px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 103.63636363636364%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Convolutional neural network stride 2 diagram"\n        title=""\n        src="/static/stride2Diagram-0703a55beb4a2fd5da9f95b2b24312c9-8f9ab.png"\n        srcset="/static/stride2Diagram-0703a55beb4a2fd5da9f95b2b24312c9-3bfbe.png 240w,\n/static/stride2Diagram-0703a55beb4a2fd5da9f95b2b24312c9-8f9ab.png 440w"\n        sizes="(max-width: 440px) 100vw, 440px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>However, what if we had shifted over our filter by one pixel instead? Notice that this would determine a different subset of the image that the second feature would focus on:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/stride1Diagram-97664e419289f5405c0163890018eec4-6daf9.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 756px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 65.60846560846561%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Convolutional neural network stride 1 diagram"\n        title=""\n        src="/static/stride1Diagram-97664e419289f5405c0163890018eec4-6daf9.png"\n        srcset="/static/stride1Diagram-97664e419289f5405c0163890018eec4-788ea.png 240w,\n/static/stride1Diagram-97664e419289f5405c0163890018eec4-046d3.png 480w,\n/static/stride1Diagram-97664e419289f5405c0163890018eec4-6daf9.png 756w"\n        sizes="(max-width: 756px) 100vw, 756px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>The value that determines how much we slide over our filter is called the <strong>stride</strong>. In practice, we often see that\nusing smaller stride values produce better performance on trained convolutional networks.</p>\n<h2>Pooling Layers</h2>\n<p>In addition to convolutional layers, there is another commonly used layer in convolutional networks: the <strong>pooling layer</strong>.\nThe purpose of pooling layers is often to more aggressively reduce the size of a given input layer, by effectively cutting down on the number of features.</p>\n<p>One of the most common types of pooling is called <strong>max pooling</strong>. As its names suggests, the max pooling layer takes the max value over an area of an input layer. This looks as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/maxPoolDiagram-b356ec7a10942a3a958b26fc51ccd16f-76aa7.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 788px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 54.314720812182735%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Convolutional neural network max pool diagram"\n        title=""\n        src="/static/maxPoolDiagram-b356ec7a10942a3a958b26fc51ccd16f-76aa7.png"\n        srcset="/static/maxPoolDiagram-b356ec7a10942a3a958b26fc51ccd16f-b0483.png 240w,\n/static/maxPoolDiagram-b356ec7a10942a3a958b26fc51ccd16f-7fdcc.png 480w,\n/static/maxPoolDiagram-b356ec7a10942a3a958b26fc51ccd16f-76aa7.png 788w"\n        sizes="(max-width: 788px) 100vw, 788px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>With pooling layers we also extend the operation depth-wise and apply it over a variably-sized area, as we did with convolutional filters.\nFor example, we could use max pooling over a <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mi>x</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">2x2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base"><span class="mord">2</span><span class="mord mathit">x</span><span class="mord">2</span></span></span></span> area that determines the segment we are applying the operation to. The depth of the output volume does not change.</p>\n<p>Zooming out, we must be careful when choosing the filter and stride size in our convolutional networks and operations such as max-pooling tend to throw away a lot of information in an input layer.</p>\n<h2>The 2011 ImageNet Winner</h2>\n<p>With all that theory in place, we are now finally ready to revisit the 2011 ImageNet-winning entry. Historically, a lot of the architectures\nthat have won past ImageNet competitions have been given catchy names because gloating rights are a thing in machine learning 🙂!</p>\n<p>The architecture that won ImageNet 2011 was called <strong>AlexNet</strong> after its principal creator Alex Krizhevsky. The architecture looked as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/alexnetDiagram-195b1fe1f83baf8c50f53df7964f585b-a0803.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 848px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 116.27358490566037%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="AlexNet convolutional neural network architecture"\n        title=""\n        src="/static/alexnetDiagram-195b1fe1f83baf8c50f53df7964f585b-a0803.png"\n        srcset="/static/alexnetDiagram-195b1fe1f83baf8c50f53df7964f585b-ee56a.png 240w,\n/static/alexnetDiagram-195b1fe1f83baf8c50f53df7964f585b-3076b.png 480w,\n/static/alexnetDiagram-195b1fe1f83baf8c50f53df7964f585b-a0803.png 848w"\n        sizes="(max-width: 848px) 100vw, 848px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Here <strong>norm</strong> refers to a specific normalization operation that was introduced to help generalization. This particular operation\nhas fallen out of favor in convolutional network architectures since then.</p>\n<p>In addition, <strong>fully connected</strong> refers to a feedforward layer we saw when we looked at feedforward neural networks. At the end of the last fully connected layer, the architecture outputted a probability distribution over 1000 labels, which is how many labels there were in the challenge.</p>\n<p>An important thing to note is many of the ideas behind the architecture of AlexNet had been introduced previously. What AlexNet\nadded that was so revolutionary was increasing the depth of the neural network in terms of number of layers.</p>\n<p>Typically as networks get more deep they get harder to train, but the University of Toronto team managed to effectively train a very deep network. Another novel contribution was the use of several stacked convolutional layers in a row, which had not been explored previously.</p>\n<p>And with that, we’ve come full circle! From humble beginnings, we’ve successfully\ndiscussed the model that triggered the modern-day resurgence of artificial intelligence. What a phenomenal milestone in our AI journey!</p>',
fields:{tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Dance Dance Convolution",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:40:37.121",description:"We discuss convolutional neural networks, a deep learning model inspired by the human visual system that has rocked the state-of-the-art in computer vision tasks."}}},pathContext:{slug:"/posts/convolutional-neural-networks/"}}}});
//# sourceMappingURL=path---posts-convolutional-neural-networks-f2dc27195e2de730ba4c.js.map